// 综艺花字 · 风格样片。标准分镜：标题 → 要点 → 数据 → 人名条 → 收尾。
// 可照搬：STYLE 取值、popText()（多层描边 + 硬投影花字）、pop()（回弹缩放）、slam()（冲击落地）、
// shake()（落地抖动）、burst()（爆炸星底）、sticker()（贴纸底板）、stripes()（斜条纹底），
// 以及 layers() 的分层写法：每个花字、贴纸各成一层，弹出、砸落、抖动都写进 pose(t)，运行时据此做运动模糊。

const STYLE = {
  color: {
    bg: "#FFD60A",
    stripe: "#FFC300",
    ink: "#111111",
    white: "#FFFFFF",
    red: "#FF2D2D",
    blue: "#1E6BFF",
  },
  font: {
    title: '"YouSheBiaoTiYuan", "Alimama FangYuanTi VF", "HarmonyOS Sans SC", "Microsoft YaHei", sans-serif',
    body: '"Alimama FangYuanTi VF", "HarmonyOS Sans SC", "Microsoft YaHei", sans-serif',
  },
};

const SCENES = { title: [0, 1.85], list: [1.85, 3.85], data: [3.85, 5.65], name: [5.65, 6.95], end: [6.95, 8] };
const COPY = {
  title: ["把想法", "变成画面"],
  subtitle: "风格样片 · STYLE SAMPLE",
  list: ["统一的配色", "统一的字体", "统一的节奏"],
  data: { value: 87, unit: "%", label: "一次通过率！" },
  name: { name: "痕继痕迹", role: "动效设计师" },
  end: "一个风格，处处一致",
};

const clamp = (v) => Math.max(0, Math.min(1, v));
// backOut：过冲约 10%。
const backOut = (v, c = 1.6) => { v = clamp(v) - 1; return 1 + (c + 1) * v * v * v + c * v * v; };
const quintOut = (v) => 1 - Math.pow(1 - clamp(v), 5);
const cubicIn = (v) => clamp(v) ** 3;
const font = (weight, size, family) => `${weight} ${Math.round(size)}px ${family}`;

// 弹出：0 → 1 带过冲，0.3 s。
function pop(t, start, dur = 0.3) { return t < start ? 0 : backOut((t - start) / dur); }
// 冲击：从 1.6 倍砸到 1 倍，0.18 s，几乎没有过渡。
function slam(t, start, dur = 0.18) { return t < start ? null : 1 + 0.6 * (1 - quintOut((t - start) / dur)); }
// 落地抖动：落地后 0.3 s 内衰减，确定性正弦。
function shake(t, start, amp) {
  const k = t - start;
  if (k < 0 || k > 0.3) return [0, 0];
  const d = amp * (1 - k / 0.3);
  return [Math.sin(k * 90) * d, Math.cos(k * 70) * d * 0.6];
}

function stripes(ctx, t, u, w, h) {
  ctx.fillStyle = STYLE.color.bg;
  ctx.fillRect(0, 0, w, h);
  ctx.save();
  ctx.fillStyle = STYLE.color.stripe;
  const step = 70 * u, off = (t * 60 * u) % step;
  ctx.translate(w / 2, h / 2);
  ctx.rotate(-Math.PI / 6);
  for (let x = -w - off; x < w; x += step) ctx.fillRect(x, -w, step / 2, w * 2);
  ctx.restore();
}

// 花字，由外到内：黑色硬投影 → 白色外描边 → 黑色内描边 → 填色。
// 两条规则保证复杂字（"画""想""赢"）的内部空隙不被填死：
// 1. 字重只写字体实际有的。优设标题圆只有一个字重，写 700/900 会被浏览器假加粗。
// 2. 描边宽度按字号封顶：外描边总宽不超过字号的 16%，内描边不超过 5%。描边是沿笔画边缘向两侧长的，太粗就会长进字内的空隙。
// 填色和内描边要反差大（白字配黑边），否则字形会糊成一团。
const TITLE_WEIGHT = 400;
function popText(ctx, text, x, y, size, fill, u, align = "center") {
  ctx.font = font(TITLE_WEIGHT, size, STYLE.font.title);
  ctx.textAlign = align;
  ctx.lineJoin = "round";
  const outer = Math.min(size * 0.16, 22 * u), inner = Math.min(size * 0.05, 6 * u), sh = outer * 0.5;
  ctx.lineWidth = outer;
  ctx.strokeStyle = STYLE.color.ink;
  ctx.strokeText(text, x + sh, y + sh);
  ctx.strokeStyle = STYLE.color.white;
  ctx.strokeText(text, x, y);
  ctx.lineWidth = inner;
  ctx.strokeStyle = STYLE.color.ink;
  ctx.strokeText(text, x, y);
  ctx.fillStyle = fill;
  ctx.fillText(text, x, y);
  ctx.textAlign = "left";
}

function burst(ctx, cx, cy, r, spikes, rot, color) {
  ctx.fillStyle = color;
  ctx.beginPath();
  for (let i = 0; i < spikes * 2; i++) {
    const a = rot + (i * Math.PI) / spikes, rr = i % 2 ? r * 0.72 : r;
    ctx.lineTo(cx + Math.cos(a) * rr, cy + Math.sin(a) * rr);
  }
  ctx.closePath();
  ctx.fill();
}

function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

// 贴纸底板：粗黑边 + 硬投影。
function sticker(ctx, x, y, w, h, color, u) {
  roundRect(ctx, x + 8 * u, y + 8 * u, w, h, 18 * u);
  ctx.fillStyle = STYLE.color.ink;
  ctx.fill();
  roundRect(ctx, x, y, w, h, 18 * u);
  ctx.fillStyle = color;
  ctx.fill();
  ctx.lineWidth = 5 * u;
  ctx.strokeStyle = STYLE.color.ink;
  ctx.stroke();
}

const within = (t, [a, b]) => t >= a && t < b;
const fadeOut = (t, [, b], dur = 0.15) => 1 - cubicIn((t - (b - dur)) / dur);
// 只用来量字宽（分层时还没有画布）。
let measurer = null;
function measure(text, f) {
  measurer ??= new OffscreenCanvas(1, 1).getContext("2d");
  measurer.font = f;
  return measurer.measureText(text).width;
}

function layers(_params, w, h) {
  const u = h / 720, out = [];
  // 底：斜条纹按当前时刻整层画（匀速慢移，不需要模糊）。
  out.push({ draw: (ctx, t) => stripes(ctx, t, u, w, h) });

  // 标题：爆炸星转着弹出，两行花字依次弹出，黑色胶囊副标题最后弹出。
  const title = SCENES.title;
  out.push({
    bounds: [-335 * u, -335 * u, 335 * u, 335 * u],
    pose: (t) => within(t, title) ? { x: w * 0.5, y: h * 0.47, rotation: t * 0.4, scale: pop(t, 0, 0.4) * fadeOut(t, title) } : null,
    draw: (ctx) => burst(ctx, 0, 0, 330 * u, 14, 0, STYLE.color.red),
  });
  out.push({
    bounds: [-220 * u, -120 * u, 230 * u, 45 * u],
    pose: (t) => within(t, title) ? { x: w * 0.5, y: h * 0.4, rotation: -0.07, scale: pop(t, 0.05) * fadeOut(t, title) } : null,
    draw: (ctx) => popText(ctx, COPY.title[0], 0, 0, 120 * u, STYLE.color.white, u),
  });
  out.push({
    bounds: [-300 * u, -130 * u, 310 * u, 50 * u],
    pose: (t) => within(t, title) ? { x: w * 0.52, y: h * 0.62, rotation: -0.07, scale: pop(t, 0.15) * fadeOut(t, title) } : null,
    draw: (ctx) => popText(ctx, COPY.title[1], 0, 0, 132 * u, STYLE.color.bg, u),
  });
  out.push({
    bounds: [-200 * u, -32 * u, 200 * u, 18 * u],
    pose: (t) => within(t, title) ? { x: w * 0.5, y: h * 0.82, rotation: 0.03, scale: pop(t, 0.45, 0.25) * fadeOut(t, title) } : null,
    draw: (ctx) => {
      ctx.font = font(700, 22 * u, STYLE.font.body);
      const tw = ctx.measureText(COPY.subtitle).width;
      roundRect(ctx, -tw / 2 - 22 * u, -30 * u, tw + 44 * u, 46 * u, 23 * u);
      ctx.fillStyle = STYLE.color.ink;
      ctx.fill();
      ctx.fillStyle = STYLE.color.white;
      ctx.textAlign = "center";
      ctx.fillText(COPY.subtitle, 0, 0);
      ctx.textAlign = "left";
    },
  });

  // 要点：彩色贴纸依次砸下，落地抖一下。
  const list = SCENES.list, colors = [STYLE.color.red, STYLE.color.blue, STYLE.color.ink];
  COPY.list.forEach((item, i) => {
    const start = list[0] + 0.1 + i * 0.28;
    out.push({
      bounds: [-232 * u, -60 * u, 240 * u, 68 * u],
      pose: (t) => {
        const sc = slam(t, start);
        if (!within(t, list) || sc == null) return null;
        const [dx, dy] = shake(t, start + 0.18, 6 * u);
        return { x: w * 0.5 + dx + (i - 1) * 40 * u, y: h * 0.28 + i * 150 * u + dy, rotation: (i % 2 ? 1 : -1) * 0.05, scale: sc * fadeOut(t, list) };
      },
      draw: (ctx) => {
        sticker(ctx, -230 * u, -58 * u, 460 * u, 116 * u, colors[i], u);
        ctx.fillStyle = STYLE.color.white;
        ctx.font = font(TITLE_WEIGHT, 54 * u, STYLE.font.title);
        ctx.textAlign = "center";
        ctx.fillText(item, 0, 20 * u);
        ctx.textAlign = "left";
      },
    });
  });

  // 数据：数字快速蹦到终值，落地瞬间砸一下再抖；对话气泡随后弹出。
  const data = SCENES.data, land = data[0] + 0.55;
  out.push({
    bounds: [-270 * u, -210 * u, 280 * u, 50 * u],
    pose: (t) => {
      if (!within(t, data)) return null;
      const sc = t < land ? 0.9 + 0.1 * clamp((t - data[0]) / 0.55) : slam(t, land, 0.2);
      const [dx, dy] = shake(t, land, 10 * u);
      return { x: w * 0.45 + dx, y: h * 0.6 + dy, rotation: -0.05, scale: sc * fadeOut(t, data) * pop(t, data[0], 0.25) };
    },
    draw: (ctx, t) => popText(ctx, `${Math.round(COPY.data.value * quintOut((t - data[0]) / 0.55))}${COPY.data.unit}`, 0, 0, 230 * u, STYLE.color.red, u),
  });
  out.push({
    bounds: [-200 * u, -52 * u, 210 * u, 100 * u],
    pose: (t) => within(t, data) ? { x: w * 0.76, y: h * 0.25, rotation: 0.08, scale: pop(t, land + 0.1, 0.3) * fadeOut(t, data) } : null,
    draw: (ctx) => {
      ctx.font = font(TITLE_WEIGHT, 40 * u, STYLE.font.title);
      const tw = ctx.measureText(COPY.data.label).width;
      // 对话气泡：白底黑边 + 小尾巴。
      ctx.beginPath();
      ctx.moveTo(-40 * u, 40 * u); ctx.lineTo(-70 * u, 92 * u); ctx.lineTo(-4 * u, 40 * u); ctx.closePath();
      ctx.fillStyle = STYLE.color.white; ctx.fill();
      ctx.lineWidth = 5 * u; ctx.strokeStyle = STYLE.color.ink; ctx.stroke();
      sticker(ctx, -tw / 2 - 28 * u, -44 * u, tw + 56 * u, 88 * u, STYLE.color.white, u);
      ctx.fillStyle = STYLE.color.ink;
      ctx.textAlign = "center";
      ctx.fillText(COPY.data.label, 0, 14 * u);
      ctx.textAlign = "left";
    },
  });

  // 人名条：白色贴纸卡片弹出，角上的小爆炸星转着弹出。
  const name = SCENES.name;
  out.push({
    bounds: [-192 * u, -72 * u, 200 * u, 80 * u],
    pose: (t) => within(t, name) ? { x: w * 0.3, y: h * 0.74, rotation: -0.04, scale: pop(t, name[0] + 0.05, 0.35) * fadeOut(t, name) } : null,
    draw: (ctx) => {
      sticker(ctx, -190 * u, -70 * u, 380 * u, 140 * u, STYLE.color.white, u);
      ctx.fillStyle = STYLE.color.ink;
      ctx.font = font(TITLE_WEIGHT, 56 * u, STYLE.font.title);
      ctx.fillText(COPY.name.name, -150 * u, 8 * u);
      ctx.fillStyle = STYLE.color.blue;
      ctx.font = font(700, 26 * u, STYLE.font.body);
      ctx.fillText(COPY.name.role, -150 * u, 48 * u);
    },
  });
  out.push({
    bounds: [-36 * u, -36 * u, 36 * u, 36 * u],
    pose: (t) => within(t, name) ? { x: w * 0.3 + 190 * u, y: h * 0.74 - 70 * u, rotation: t * 2, scale: pop(t, name[0] + 0.25, 0.3) * fadeOut(t, name) } : null,
    draw: (ctx) => burst(ctx, 0, 0, 34 * u, 8, 0, STYLE.color.red),
  });

  // 收尾：逐字从下方蹦出，后半句换红色，落地后随节拍轻轻起伏。每个字一层。
  const end = SCENES.end, chars = [...COPY.end], f = font(TITLE_WEIGHT, 84 * u, STYLE.font.title);
  const widths = chars.map((c) => measure(c, f));
  let x = w / 2 - widths.reduce((a, b) => a + b, 0) / 2;
  chars.forEach((c, i) => {
    const start = end[0] + 0.05 + i * 0.05, cx = x + widths[i] / 2;
    out.push({
      bounds: [-60 * u, -95 * u, 66 * u, 40 * u],
      pose: (t) => {
        if (t < start) return null;
        const k = pop(t, start, 0.3), bob = t > start + 0.3 ? Math.sin((t - start) * 9 + i) * 4 * u : 0;
        return { x: cx, y: h * 0.56 - (1 - k) * 60 * u + bob, rotation: (i % 2 ? 1 : -1) * 0.04, scale: k };
      },
      draw: (ctx) => popText(ctx, c, 0, 0, 84 * u, i >= 5 ? STYLE.color.red : STYLE.color.white, u),
    });
    x += widths[i];
  });
  return out;
}

export default {
  name: "综艺花字 · 样片", kind: "generator", mode: "dynamic",
  nameEnglish: "Variety Captions · Sample",
  params: [],
  // 弹、砸、抖都快，用 180° 快门已经很有冲击感；想更"糊"可以加到 270°。
  motionBlur: { shutter: 180 },
  layers,
};
